Object.assign(window.DYLEAN_DATA.files["Library/Init/Data/Order/ClassesExtra.lean"],{"text":"/-\nCopyright (c) 2025 Lean FRO, LLC. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Paul Reichert\n-/\nmodule\n\nprelude\npublic import Init.Data.Ord.Basic\n\nnamespace Std\n\n/--\nThis typeclass states that the synthesized `Ord α` instance is compatible with the `LE α`\ninstance. This means that according to `compare`, the following are equivalent:\n\n* `a` is less than or equal to `b` according to `compare`.\n* `b` is greater than or equal to `b` according to `compare`.\n* `a ≤ b` holds.\n\n`LawfulOrderOrd α` automatically entails that `Ord α` is oriented (see `OrientedOrd α`)\nand that `LE α` is total.\n\n`Ord α` and `LE α` mutually determine each other in the presence of `LawfulOrderOrd α`.\n-/\npublic class LawfulOrderOrd (α : Type u) [Ord α] [LE α] where\n  isLE_compare : ∀ a b : α, (compare a b).isLE ↔ a ≤ b\n  isGE_compare : ∀ a b : α, (compare a b).isGE ↔ b ≤ a\n\npublic theorem LawfulOrderOrd.isLE_compare_eq_false {α : Type u} [Ord α] [LE α] [LawfulOrderOrd α] {a b : α} :\n    (compare a b).isLE = false ↔ ¬ a ≤ b := by\n  simp [← isLE_compare]\n\npublic theorem LawfulOrderOrd.isGE_compare_eq_false {α : Type u} [Ord α] [LE α] [LawfulOrderOrd α] {a b : α} :\n    (compare a b).isGE = false ↔ ¬ b ≤ a := by\n  simp [← isGE_compare]\n\npublic abbrev LawfulOrderCmp (cmp : α → α → Ordering) [LE α] := @Std.LawfulOrderOrd α ⟨cmp⟩ _\n\nend Std\n","refs":[[25,13,25,27,"267ef27c0e89",true],[25,42,25,45,"972bbdeee361",false],[25,50,25,52,"d8d48ca50f47",false],[26,29,26,36,"ec3baf8de43f",false],[26,42,26,46,"49eeb3b1fa10",false],[27,29,27,36,"ec3baf8de43f",false],[27,42,27,46,"23a983bcd15b",false],[29,66,29,69,"972bbdeee361",false],[29,74,29,76,"d8d48ca50f47",false],[29,81,29,95,"267ef27c0e89",false],[30,5,30,12,"ec3baf8de43f",false],[30,18,30,22,"49eeb3b1fa10",false],[30,25,30,30,"e97ff9f8035d",false],[31,10,31,22,"3aa531288ac4",false],[33,66,33,69,"972bbdeee361",false],[33,74,33,76,"d8d48ca50f47",false],[33,81,33,95,"267ef27c0e89",false],[34,5,34,12,"ec3baf8de43f",false],[34,18,34,22,"23a983bcd15b",false],[34,25,34,30,"e97ff9f8035d",false],[35,10,35,22,"b49fb1498e29",false],[37,44,37,52,"03fe9402309a",false],[37,55,37,57,"d8d48ca50f47",false],[37,65,37,83,"267ef27c0e89",false]]});
